-- Every statement is an upsert on a natural key, so re-running is safe.

-- Sources. Keyed on url, which is unique per source in this set.
insert into public.expat_citations
  (publisher, url, official, published_on, effective_from, observed_at, language, excerpt)
values ('Tbilisi Transport Company', 'https://ttc.com.ge/en/tariff/10', true, null, null,
        '2026-10-24T00:00:00Z'::timestamptz, 'en', 'Fares for metro, bus, minibus and the Bagebi University ropeway: "1 GEL 90 minutes unlimited free travel"; 3 GEL one day; 20 GEL one week; 40 GEL one month. The 90 minute package can be paid with a Metromoney card or bank cards. Packages of one day and longer only on a subscription card. Paying by mobile app or cash does not give the 90 minute package. Cards sold at metro station payment offices and Bank of Georgia express branches, 2 GEL each; keep the receipt to restore a lost card.')
on conflict do nothing;
insert into public.expat_citations
  (publisher, url, official, published_on, effective_from, observed_at, language, excerpt)
values ('TKT.GE (Georgian Railway ticket sales)', 'https://tkt.ge/en/transport/railway-tickets/tbilisi/batumi', false, null, null,
        '2026-10-24T00:00:00Z'::timestamptz, 'en', 'Georgian Railway tickets bought online; "Your purchased ticket arrives as a QR code to your email" and is shown on the phone to board. "Passengers must carry a valid ID card or an international passport when traveling by train." Children aged 5 to 10: 50% discount. Routes listed on tkt.ge/railway include Tbilisi to Batumi, Poti, Kutaisi, Ureki and Ozurgeti, with Zugdidi among popular destinations.')
on conflict do nothing;
insert into public.expat_citations
  (publisher, url, official, published_on, effective_from, observed_at, language, excerpt)
values ('Madloba.info', 'https://madloba.info/en/faq/city-transport-and-parking/batumi-public-transport-fares/', false, null, null,
        '2026-10-24T00:00:00Z'::timestamptz, 'en', 'Batumi city buses are cheapest with the Batumi Card transport card; a contactless bank card costs more, "about 1 GEL". Municipal buses do not take cash; minibuses do. Fares are set by the municipal company Batumi Autotransport. Checked Oct. 2, 2026.')
on conflict do nothing;
insert into public.expat_citations
  (publisher, url, official, published_on, effective_from, observed_at, language, excerpt)
values ('Madloba.info', 'https://madloba.info/en/faq/city-transport-and-parking/taxi-in-tbilisi/', false, null, null,
        '2026-10-24T00:00:00Z'::timestamptz, 'en', 'Recommends "the Bolt, Yandex Go or Maxim apps"; with an app "you see the price in advance". Street taxis have no meter, so "agree the fare before you get in". Checked Oct. 2, 2026.')
on conflict do nothing;
insert into public.expat_citations
  (publisher, url, official, published_on, effective_from, observed_at, language, excerpt)
values ('Madloba.info', 'https://madloba.info/en/faq/mobile-and-internet/buying-a-sim-card-in-georgia/', false, null, null,
        '2026-10-24T00:00:00Z'::timestamptz, 'en', '"You need your passport to buy one, and the operators also offer eSIMs." Three operators: Magti, Silknet and Cellfie (formerly Beeline), with shops including at Tbilisi, Kutaisi and Batumi airports. An eSIM can be had online before arrival with a photo of the passport. "Magti usually has the best coverage in the mountains." Operators change plans often. Checked Oct. 2, 2026.')
on conflict do nothing;
