on conflict do nothing;

-- Keep one row per (publisher, url): re-running must not accumulate copies.
delete from public.expat_citations a
using public.expat_citations b
where a.publisher = b.publisher
  and a.url is not distinct from b.url
  and a.ctid > b.ctid
  and not exists (select 1 from public.expat_fact_citations fc where fc.citation_id = a.id)
  and not exists (select 1 from public.expat_cost_observations co where co.citation_id = a.id)
  and not exists (select 1 from public.expat_places p where p.citation_id = a.id);

-- public-transport
insert into public.expat_topics
  (slug, country, domain, pathway, content, fact_class, register, sort_order,
   published, needs_review, review_reason, last_verified_at, review_due_at)
values ('public-transport', 'GE', 'TRANSPORT', 'LIVE', '{"en":{"title":"Getting around: metro, buses, trains and taxis","summary":"In Tbilisi the metro and buses are cheap and simple once you have a card. Between cities you can take the train or a minibus, and for taxis an app is the easy way.","sections":[{"kind":"SHORT_ANSWER","heading":"The short answer","body":"In Tbilisi one ride on the metro, a city bus or a city minibus costs 1 lari and gives you 90 minutes of travel. Tap a Metromoney card or your own bank card on the reader. If you travel every day, a pass on a transport card works out cheaper. For a taxi, use an app so you see the price before you get in."},{"kind":"COST","heading":"Tbilisi fares","body":"1 lari for 90 minutes, 3 lari for a day, 20 lari for a week, 40 lari for a month. These cover the metro, buses, minibuses and the Bagebi University ropeway. Passes of a day or longer only work on a transport card, not on a bank card. If you pay in the mobile app or with cash, you do not get the 90 minutes. These are the Tbilisi Transport Company fares as we read them in October 2026."},{"kind":"WHERE","heading":"Where to get a transport card","body":"At the ticket office of any metro station and at Bank of Georgia express branches. The card itself costs 2 lari. Keep the receipt, because it is the only way to get your money back on a card you lose or break."},{"kind":"PRACTICAL","heading":"Batumi, trains and minibuses","body":"In Batumi the city buses are cheapest with the Batumi Card. A contactless bank card also works but costs a little more, and city buses do not take cash, though minibuses do. Trains from Tbilisi go to Batumi, Kutaisi, Poti, Zugdidi, Ozurgeti and other towns. Buy the ticket online, it arrives by email as a QR code, and carry your passport, because without an ID you will not be let on. Intercity minibuses, called marshrutkas, leave from the bus stations. Times and prices depend on the route, so ask at the station."},{"kind":"PRACTICAL","heading":"Taxis","body":"Bolt, Yandex Go and Maxim all work in Tbilisi and show the price before you order. Street taxis have no meter, so agree the price before you sit down."}]},"ka":{"title":"გადაადგილება: მეტრო, ავტობუსი, მატარებელი და ტაქსი","summary":"თბილისში მეტრო და ავტობუსი იაფი და მარტივია, როცა ბარათი გაქვთ. ქალაქებს შორის შეგიძლიათ მატარებლით ან მიკროავტობუსით იმგზავროთ, ტაქსისთვის კი აპლიკაცია ყველაზე მოსახერხებელია.","sections":[{"kind":"SHORT_ANSWER","heading":"მოკლე პასუხი","body":"თბილისში მეტროში, ქალაქის ავტობუსში ან მიკროავტობუსში ერთი მგზავრობა 1 ლარი ღირს და 90 წუთის განმავლობაში მოქმედებს. მიადეთ წამკითხველს მეტრომანის ბარათი ან თქვენი საბანკო ბარათი. თუ ყოველდღე მგზავრობთ, სამგზავრო ბარათზე აბონემენტი უფრო იაფი გამოვა. ტაქსისთვის გამოიყენეთ აპლიკაცია, რომ ფასი ჩაჯდომამდე იცოდეთ."},{"kind":"COST","heading":"ტარიფები თბილისში","body":"1 ლარი 90 წუთზე, 3 ლარი ერთ დღეზე, 20 ლარი ერთ კვირაზე, 40 ლარი ერთ თვეზე. ეს მოქმედებს მეტროზე, ავტობუსზე, მიკროავტობუსზე და ბაგები-უნივერსიტეტის საბაგიროზე. ერთდღიანი და უფრო გრძელი აბონემენტი მხოლოდ სამგზავრო ბარათზე მუშაობს, საბანკო ბარათზე არა. მობილური აპლიკაციით ან ნაღდი ფულით გადახდისას 90 წუთი არ მოქმედებს. ეს თბილისის სატრანსპორტო კომპანიის ტარიფებია, როგორც 2026 წლის ოქტომბერში წავიკითხეთ."},{"kind":"WHERE","heading":"სად აიღოთ სამგზავრო ბარათი","body":"ნებისმიერი მეტროსადგურის სალაროში და საქართველოს ბანკის ექსპრეს ფილიალებში. ბარათი 2 ლარი ღირს. შეინახეთ ქვითარი, რადგან დაკარგული ან დაზიანებული ბარათის აღდგენა მხოლოდ მისით შეიძლება."},{"kind":"PRACTICAL","heading":"ბათუმი, მატარებელი და მარშრუტკა","body":"ბათუმში ქალაქის ავტობუსი ყველაზე იაფია ბათუმის ბარათით. უკონტაქტო საბანკო ბარათიც მუშაობს, ოღონდ ცოტა უფრო ძვირი ჯდება. ქალაქის ავტობუსი ნაღდ ფულს არ იღებს, მიკროავტობუსი კი იღებს. თბილისიდან მატარებელი დადის ბათუმში, ქუთაისში, ფოთში, ზუგდიდში, ოზურგეთში და სხვა ქალაქებში. ბილეთი იყიდეთ ონლაინ, ელფოსტაზე QR კოდად მოგივათ. თან იქონიეთ პასპორტი, პირადობის დამადასტურებელი დოკუმენტის გარეშე მატარებელში არ შეგიშვებენ. ქალაქთაშორისი მარშრუტკები ავტოსადგურებიდან გადის. დრო და ფასი მარშრუტზეა დამოკიდებული, ამიტომ იკითხეთ ადგილზე."},{"kind":"PRACTICAL","heading":"ტაქსი","body":"თბილისში მუშაობს Bolt, Yandex Go და Maxim, და სამივე შეკვეთამდე გაჩვენებთ ფასს. ქუჩის ტაქსს მრიცხველი არ აქვს, ამიტომ ფასზე ჩაჯდომამდე შეთანხმდით."}]},"ru":{"title":"Как передвигаться: метро, автобусы, поезда и такси","summary":"В Тбилиси метро и автобусы дешёвые и простые, если у вас есть карта. Между городами можно ехать поездом или маршруткой, а такси проще всего заказывать через приложение.","sections":[{"kind":"SHORT_ANSWER","heading":"Коротко","body":"В Тбилиси одна поездка на метро, городском автобусе или маршрутке стоит 1 лари и действует 90 минут. Приложите к валидатору карту Metromoney или свою банковскую карту. Если ездите каждый день, абонемент на транспортной карте выйдет дешевле. Такси лучше заказывать через приложение, чтобы видеть цену заранее."},{"kind":"COST","heading":"Тарифы в Тбилиси","body":"1 лари за 90 минут, 3 лари за день, 20 лари за неделю, 40 лари за месяц. Это действует в метро, автобусах, маршрутках и на канатной дороге Багеби Университет. Абонементы на день и дольше работают только на транспортной карте, не на банковской. При оплате через мобильное приложение или наличными 90 минут не действуют. Это тарифы Тбилисской транспортной компании, как мы их прочитали в октябре 2026 года."},{"kind":"WHERE","heading":"Где взять транспортную карту","body":"В кассе любой станции метро и в экспресс филиалах Bank of Georgia. Сама карта стоит 2 лари. Сохраните чек: только по нему можно восстановить потерянную или сломанную карту."},{"kind":"PRACTICAL","heading":"Батуми, поезда и маршрутки","body":"В Батуми городские автобусы дешевле всего с Batumi Card. Бесконтактная банковская карта тоже работает, но выходит чуть дороже. Городские автобусы наличные не берут, маршрутки берут. Из Тбилиси поезда ходят в Батуми, Кутаиси, Поти, Зугдиди, Озургети и другие города. Билет покупайте онлайн, он придёт на почту QR кодом. Возьмите паспорт: без документа в поезд не пустят. Междугородние маршрутки уходят с автовокзалов. Время и цена зависят от маршрута, так что спрашивайте на месте."},{"kind":"PRACTICAL","heading":"Такси","body":"В Тбилиси работают Bolt, Yandex Go и Maxim, и все показывают цену до заказа. У уличного такси нет счётчика, поэтому договоритесь о цене до того, как сядете."}]},"tr":{"title":"Ulaşım: metro, otobüs, tren ve taksi","summary":"Tiflis''te metro ve otobüs, bir kartınız olduğunda ucuz ve kolaydır. Şehirler arasında tren ya da minibüsle gidebilirsiniz, taksi için en kolayı uygulamadır.","sections":[{"kind":"SHORT_ANSWER","heading":"Kısaca","body":"Tiflis''te metro, şehir otobüsü ya da şehir içi minibüste bir yolculuk 1 lari tutar ve 90 dakika geçerlidir. Metromoney kartınızı ya da kendi banka kartınızı okutun. Her gün yolculuk ediyorsanız ulaşım kartına abonman daha ucuza gelir. Taksi için uygulama kullanın, böylece fiyatı binmeden görürsünüz."},{"kind":"COST","heading":"Tiflis''te ücretler","body":"90 dakika 1 lari, bir gün 3 lari, bir hafta 20 lari, bir ay 40 lari. Metro, otobüs, minibüs ve Bagebi Üniversite teleferiğinde geçerlidir. Bir günlük ve daha uzun abonmanlar yalnızca ulaşım kartında çalışır, banka kartında çalışmaz. Mobil uygulamayla ya da nakit ödediğinizde 90 dakika hakkı olmaz. Bunlar Tiflis Ulaşım Şirketi''nin ücretleri, Ekim 2026''da okuduğumuz şekliyle."},{"kind":"WHERE","heading":"Ulaşım kartı nereden alınır","body":"Herhangi bir metro istasyonunun gişesinden ve Bank of Georgia ekspres şubelerinden. Kartın kendisi 2 lari. Fişi saklayın, kaybolan ya da bozulan kartı geri almanın tek yolu bu."},{"kind":"PRACTICAL","heading":"Batum, trenler ve minibüsler","body":"Batum''da şehir otobüsleri en ucuz Batumi Card ile. Temassız banka kartı da çalışır ama biraz daha pahalıdır. Şehir otobüsleri nakit almaz, minibüsler alır. Tiflis''ten trenler Batum, Kutaisi, Poti, Zugdidi, Ozurgeti ve başka şehirlere gider. Bileti internetten alın, e-postanıza QR kod olarak gelir. Pasaportunuzu yanınıza alın, kimlik olmadan trene bindirilmezsiniz. Şehirlerarası minibüsler, yani marşrutkalar, otogarlardan kalkar. Saat ve fiyat güzergâha göre değişir, otogarda sorun."},{"kind":"PRACTICAL","heading":"Taksi","body":"Tiflis''te Bolt, Yandex Go ve Maxim çalışır ve hepsi siparişten önce fiyatı gösterir. Sokak taksilerinde taksimetre yoktur, binmeden fiyatta anlaşın."}]},"ar":{"title":"التنقل: المترو والحافلات والقطارات وسيارات الأجرة","summary":"في تبليسي المترو والحافلات رخيصة وسهلة متى صارت معك بطاقة. وبين المدن تستطيع ركوب القطار أو الميني باص، أما سيارة الأجرة فأسهل طريقة لها هي التطبيق.","sections":[{"kind":"SHORT_ANSWER","heading":"باختصار","body":"في تبليسي تكلّف الرحلة الواحدة بالمترو أو الحافلة أو الميني باص داخل المدينة لاري واحدًا، وتصلح لمدة 90 دقيقة. مرّر بطاقة Metromoney أو بطاقتك البنكية على الجهاز. وإذا كنت تتنقل كل يوم فالاشتراك على بطاقة النقل أوفر. ولسيارة الأجرة استخدم تطبيقًا لترى السعر قبل أن تركب."},{"kind":"COST","heading":"الأسعار في تبليسي","body":"لاري واحد لـ 90 دقيقة، و3 لاري ليوم، و20 لاري لأسبوع، و40 لاري لشهر. تشمل المترو والحافلات والميني باص وتلفريك باغيبي الجامعة. الاشتراك ليوم أو أكثر يعمل على بطاقة النقل فقط، لا على البطاقة البنكية. وإذا دفعت عبر التطبيق أو نقدًا فلا تحصل على الـ 90 دقيقة. هذه أسعار شركة النقل في تبليسي كما قرأناها في أكتوبر 2026."},{"kind":"WHERE","heading":"من أين تحصل على بطاقة النقل","body":"من شباك التذاكر في أي محطة مترو، ومن فروع Bank of Georgia السريعة. ثمن البطاقة نفسها 2 لاري. احتفظ بالإيصال، فهو الطريقة الوحيدة لاسترجاع رصيد بطاقة ضاعت أو تلفت."},{"kind":"PRACTICAL","heading":"باتومي والقطارات والميني باص","body":"في باتومي أرخص طريقة لركوب الحافلات هي Batumi Card. البطاقة البنكية اللاتلامسية تعمل أيضًا لكنها أغلى قليلًا. حافلات المدينة لا تقبل النقد، أما الميني باص فيقبله. من تبليسي تذهب القطارات إلى باتومي وكوتايسي وبوتي وزوغديدي وأوزورغيتي ومدن أخرى. اشترِ التذكرة عبر الإنترنت وستصلك بالبريد الإلكتروني على شكل رمز QR. خذ جوازك معك، فبدون هوية لن يسمحوا لك بالصعود. الميني باص بين المدن، ويسمّونه مارشروتكا، ينطلق من محطات الحافلات، والمواعيد والأسعار تختلف حسب الخط، فاسأل في المحطة."},{"kind":"PRACTICAL","heading":"سيارات الأجرة","body":"في تبليسي تعمل تطبيقات Bolt وYandex Go وMaxim، وكلها تعرض السعر قبل الطلب. سيارات الأجرة في الشارع بلا عدّاد، فاتفق على السعر قبل أن تركب."}]},"he":{"title":"להתנייד: מטרו, אוטובוסים, רכבות ומוניות","summary":"בטביליסי המטרו והאוטובוסים זולים ופשוטים ברגע שיש לכם כרטיס. בין ערים נוסעים ברכבת או במיניבוס, ולמונית הכי קל להזמין באפליקציה.","sections":[{"kind":"SHORT_ANSWER","heading":"בקצרה","body":"בטביליסי נסיעה אחת במטרו, באוטובוס עירוני או במיניבוס עירוני עולה לארי אחד ותקפה ל־90 דקות. מצמידים לקורא כרטיס Metromoney או את כרטיס האשראי שלכם. אם נוסעים כל יום, מנוי על כרטיס תחבורה יוצא זול יותר. למונית השתמשו באפליקציה, כדי לראות את המחיר לפני שעולים."},{"kind":"COST","heading":"מחירים בטביליסי","body":"לארי אחד ל־90 דקות, 3 לארי ליום, 20 לארי לשבוע, 40 לארי לחודש. זה תקף במטרו, באוטובוסים, במיניבוסים וברכבל באגבי אוניברסיטה. מנוי ליום ומעלה עובד רק על כרטיס תחבורה, לא על כרטיס אשראי. מי שמשלם באפליקציה או במזומן לא מקבל את 90 הדקות. אלה המחירים של חברת התחבורה של טביליסי, כפי שקראנו אותם באוקטובר 2026."},{"kind":"WHERE","heading":"איפה משיגים כרטיס תחבורה","body":"בקופה של כל תחנת מטרו ובסניפי האקספרס של Bank of Georgia. הכרטיס עצמו עולה 2 לארי. שמרו את הקבלה, כי רק איתה אפשר לשחזר כרטיס שאבד או נשבר."},{"kind":"PRACTICAL","heading":"בטומי, רכבות ומיניבוסים","body":"בבטומי האוטובוסים העירוניים הכי זולים עם Batumi Card. כרטיס אשראי ללא מגע עובד גם, אבל עולה קצת יותר. האוטובוסים העירוניים לא מקבלים מזומן, המיניבוסים כן. מטביליסי יש רכבות לבטומי, קוטאיסי, פוטי, זוגדידי, אוזורגטי ועוד. קונים כרטיס באינטרנט והוא מגיע במייל כקוד QR. קחו דרכון, כי בלי תעודה מזהה לא יתנו לכם לעלות. מיניבוסים בין עירוניים, שנקראים מרשרוטקות, יוצאים מתחנות האוטובוס המרכזיות. השעות והמחירים תלויים בקו, אז שאלו בתחנה."},{"kind":"PRACTICAL","heading":"מוניות","body":"בטביליסי עובדות Bolt, Yandex Go ו־Maxim, וכולן מראות מחיר לפני ההזמנה. למוניות ברחוב אין מונה, אז סגרו מחיר לפני שאתם עולים."}]}}'::jsonb,
        'FEE', 'OFFICIAL_REQUIREMENT', 50,
        true, false, null,
        now(), now() + interval '90 days')
