insert into public.expat_topic_facts
  (topic_id, fact_key, fact_class, register, availability, statement, value,
   applies_to_nationalities, needs_review)
select id, 'tbilisi-fares', 'FEE', 'OFFICIAL_REQUIREMENT', 'ESTABLISHED',
       '{"en":"Tbilisi public transport costs 1 lari for 90 minutes of unlimited travel, 3 lari for a day, 20 lari for a week and 40 lari for a month. Passes of a day or longer only work on a transport card, which costs 2 lari.","ka":"თბილისის საზოგადოებრივი ტრანსპორტი ღირს 1 ლარი 90 წუთის შეუზღუდავ მგზავრობაზე, 3 ლარი ერთ დღეზე, 20 ლარი ერთ კვირაზე და 40 ლარი ერთ თვეზე. ერთდღიანი და უფრო გრძელი აბონემენტი მხოლოდ სამგზავრო ბარათზე მოქმედებს, რომელიც 2 ლარი ღირს.","ru":"Общественный транспорт Тбилиси стоит 1 лари за 90 минут неограниченных поездок, 3 лари за день, 20 лари за неделю и 40 лари за месяц. Абонементы на день и дольше работают только на транспортной карте, которая стоит 2 лари.","tr":"Tiflis toplu taşıması 90 dakika sınırsız yolculuk için 1 lari, bir gün için 3 lari, bir hafta için 20 lari ve bir ay için 40 lari tutar. Bir günlük ve daha uzun abonmanlar yalnızca 2 lari olan ulaşım kartında geçerlidir.","ar":"تكلّف المواصلات العامة في تبليسي لاريًا واحدًا لـ 90 دقيقة من التنقل غير المحدود، و3 لاري ليوم، و20 لاري لأسبوع، و40 لاري لشهر. الاشتراك ليوم أو أكثر يعمل فقط على بطاقة النقل وثمنها 2 لاري.","he":"התחבורה הציבורית בטביליסי עולה לארי אחד ל־90 דקות של נסיעות ללא הגבלה, 3 לארי ליום, 20 לארי לשבוע ו־40 לארי לחודש. מנוי ליום ומעלה עובד רק על כרטיס תחבורה, שעולה 2 לארי."}'::jsonb, '{"currency":"GEL","minutes90":1,"day":3,"week":20,"month":40,"card":2}'::jsonb, null,
       false
