insert into public.expat_topic_facts
  (topic_id, fact_key, fact_class, register, availability, statement, value,
   applies_to_nationalities, needs_review)
select id, 'batumi-card-and-taxi-apps', 'PROCESS', 'PRACTICAL_CONTEXT', 'ESTABLISHED',
       '{"en":"Batumi city buses are cheapest with the Batumi Card, a contactless bank card costs more, and city buses do not take cash. In Tbilisi, taxi apps such as Bolt, Yandex Go and Maxim show the price in advance, while street taxis have no meter.","ka":"ბათუმში ქალაქის ავტობუსი ყველაზე იაფია ბათუმის ბარათით, უკონტაქტო საბანკო ბარათით უფრო ძვირია, ნაღდ ფულს კი ქალაქის ავტობუსი არ იღებს. თბილისში ტაქსის აპლიკაციები, მაგალითად Bolt, Yandex Go და Maxim, ფასს წინასწარ აჩვენებს, ქუჩის ტაქსს კი მრიცხველი არ აქვს.","ru":"Городские автобусы Батуми дешевле всего с Batumi Card, бесконтактная банковская карта дороже, а наличные городские автобусы не берут. В Тбилиси приложения такси, например Bolt, Yandex Go и Maxim, показывают цену заранее, а у уличного такси нет счётчика.","tr":"Batum şehir otobüsleri en ucuz Batumi Card ile, temassız banka kartı daha pahalıdır ve şehir otobüsleri nakit almaz. Tiflis''te Bolt, Yandex Go ve Maxim gibi taksi uygulamaları fiyatı önceden gösterir, sokak taksilerinde ise taksimetre yoktur.","ar":"حافلات باتومي أرخص مع Batumi Card، والبطاقة البنكية اللاتلامسية أغلى، وحافلات المدينة لا تقبل النقد. وفي تبليسي تعرض تطبيقات الأجرة مثل Bolt وYandex Go وMaxim السعر مسبقًا، أما سيارات الأجرة في الشارع فبلا عدّاد.","he":"האוטובוסים העירוניים בבטומי הכי זולים עם Batumi Card, כרטיס אשראי ללא מגע יקר יותר, והאוטובוסים העירוניים לא מקבלים מזומן. בטביליסי אפליקציות מוניות כמו Bolt, Yandex Go ו־Maxim מראות את המחיר מראש, ולמוניות ברחוב אין מונה."}'::jsonb, null, null,
       false
