insert into public.expat_topics
  (slug, country, domain, pathway, content, fact_class, register, sort_order,
   published, needs_review, review_reason, last_verified_at, review_due_at)
values ('mobile-and-internet', 'GE', 'DAILY_LIFE', 'LIVE', '{"en":{"title":"A phone number and internet at home","summary":"Getting a Georgian number is quick. Bring your passport to an operator shop and you can walk out connected. Home internet is usually fibre and is easy to set up.","sections":[{"kind":"SHORT_ANSWER","heading":"The short answer","body":"There are three mobile operators: Magti, Silknet and Cellfie. Go to one of their shops with your passport, because the number is registered in your name. If your phone takes an eSIM, the operators offer that too, and you can even set one up online before you arrive."},{"kind":"WHERE","heading":"Where to buy","body":"At the operators'' own shops in every city, and at the airports in Tbilisi, Kutaisi and Batumi. Airport shops are handy on day one. Magti sells SIM cards for tourists at the airports."},{"kind":"PRACTICAL","heading":"Which operator","body":"All three work well in the cities. In the mountains Magti usually has the best coverage, which matters if you travel to places like Svaneti or Kazbegi. Plans and prices change often, so look at the operator''s own website for what is on offer today. We do not list prices here for that reason."},{"kind":"PRACTICAL","heading":"Internet at home","body":"Most homes in the cities can get fibre optic internet, and the operators often sell it together with TV. Many rented flats already have internet, so ask the owner whose name the contract is in and whether it is included in the rent. To sign a new contract, bring your passport and the address."},{"kind":"NOTES","heading":"Before you buy an eSIM","body":"Check that your phone supports eSIM and is not locked to an operator back home. Magti lets you activate an eSIM in its MyMagti app."}]},"ka":{"title":"ტელეფონის ნომერი და ინტერნეტი სახლში","summary":"ქართული ნომრის აღება სწრაფად ხდება. მიიტანეთ პასპორტი ოპერატორის მაღაზიაში და იქიდან უკვე კავშირით გამოხვალთ. სახლის ინტერნეტი, როგორც წესი, ოპტიკურია და მარტივად ერთდება.","sections":[{"kind":"SHORT_ANSWER","heading":"მოკლე პასუხი","body":"მობილური ოპერატორი სამია: მაგთი, სილქნეტი და სელფი. მიდით რომელიმე მათგანის მაღაზიაში პასპორტით, რადგან ნომერი თქვენს სახელზე რეგისტრირდება. თუ თქვენი ტელეფონი eSIM-ს იღებს, ოპერატორები ამასაც გთავაზობენ, და მისი გააქტიურება ჩამოსვლამდე ონლაინაც შეგიძლიათ."},{"kind":"WHERE","heading":"სად იყიდოთ","body":"ოპერატორების მაღაზიებში ყველა ქალაქში და თბილისის, ქუთაისისა და ბათუმის აეროპორტებში. აეროპორტის მაღაზია პირველ დღეს ძალიან მოსახერხებელია. მაგთი აეროპორტებში ტურისტულ სიმ ბარათებს ყიდის."},{"kind":"PRACTICAL","heading":"რომელი ოპერატორი","body":"სამივე კარგად მუშაობს ქალაქებში. მთაში, როგორც წესი, მაგთის აქვს საუკეთესო დაფარვა, რაც მნიშვნელოვანია, თუ სვანეთში ან ყაზბეგში აპირებთ წასვლას. ტარიფები და ფასები ხშირად იცვლება, ამიტომ დღევანდელი შეთავაზება ოპერატორის საიტზე ნახეთ. ამ მიზეზით ფასებს აქ არ ვწერთ."},{"kind":"PRACTICAL","heading":"ინტერნეტი სახლში","body":"ქალაქებში სახლების უმეტესობაში ოპტიკური ინტერნეტის შეყვანა შეიძლება და ოპერატორები მას ხშირად ტელევიზიასთან ერთად ყიდიან. ბევრ ნაქირავებ ბინაში ინტერნეტი უკვე არის, ამიტომ ჰკითხეთ მესაკუთრეს, ვის სახელზეა ხელშეკრულება და შედის თუ არა ქირაში. ახალი ხელშეკრულებისთვის წაიღეთ პასპორტი და იცოდეთ მისამართი."},{"kind":"NOTES","heading":"სანამ eSIM-ს იყიდით","body":"გადაამოწმეთ, რომ თქვენი ტელეფონი eSIM-ს უჭერს მხარს და სამშობლოს ოპერატორზე დაბლოკილი არ არის. მაგთი eSIM-ის გააქტიურების საშუალებას MyMagti აპლიკაციაში იძლევა."}]},"ru":{"title":"Номер телефона и домашний интернет","summary":"Получить грузинский номер можно быстро. Придите с паспортом в салон оператора и выйдете уже на связи. Домашний интернет обычно оптоволоконный и подключается легко.","sections":[{"kind":"SHORT_ANSWER","heading":"Коротко","body":"Мобильных операторов три: Magti, Silknet и Cellfie. Идите в салон любого из них с паспортом, потому что номер регистрируется на ваше имя. Если телефон поддерживает eSIM, операторы предлагают и его, причём оформить его можно онлайн ещё до приезда."},{"kind":"WHERE","heading":"Где купить","body":"В салонах операторов в любом городе и в аэропортах Тбилиси, Кутаиси и Батуми. Салон в аэропорту удобен в первый день. Magti продаёт в аэропортах туристические SIM карты."},{"kind":"PRACTICAL","heading":"Какого оператора выбрать","body":"В городах хорошо работают все три. В горах лучшее покрытие обычно у Magti, это важно, если поедете в Сванетию или Казбеги. Тарифы и цены часто меняются, поэтому смотрите актуальные предложения на сайте оператора. По этой причине цен здесь нет."},{"kind":"PRACTICAL","heading":"Интернет дома","body":"В большинстве домов в городах можно провести оптоволокно, и операторы часто продают его вместе с ТВ. Во многих съёмных квартирах интернет уже есть, так что спросите хозяина, на кого оформлен договор и входит ли он в аренду. Для нового договора возьмите паспорт и знайте адрес."},{"kind":"NOTES","heading":"Перед покупкой eSIM","body":"Проверьте, что телефон поддерживает eSIM и не привязан к оператору у вас дома. У Magti eSIM можно активировать в приложении MyMagti."}]},"tr":{"title":"Telefon numarası ve evde internet","summary":"Gürcü numarası almak hızlıdır. Pasaportunuzla bir operatör mağazasına gidin, bağlanmış olarak çıkarsınız. Ev interneti genellikle fiberdir ve kolayca kurulur.","sections":[{"kind":"SHORT_ANSWER","heading":"Kısaca","body":"Üç mobil operatör var: Magti, Silknet ve Cellfie. Birinin mağazasına pasaportunuzla gidin, çünkü numara sizin adınıza kaydedilir. Telefonunuz eSIM destekliyorsa operatörler bunu da sunar, hatta gelmeden önce internetten alabilirsiniz."},{"kind":"WHERE","heading":"Nereden alınır","body":"Her şehirde operatörlerin kendi mağazalarından ve Tiflis, Kutaisi ve Batum havalimanlarından. Havalimanı mağazası ilk gün için pratiktir. Magti havalimanlarında turistlere SIM kart satar."},{"kind":"PRACTICAL","heading":"Hangi operatör","body":"Şehirlerde üçü de iyi çalışır. Dağlarda genellikle en iyi kapsama Magti''dedir, Svaneti ya da Kazbegi gibi yerlere gidecekseniz bu önemlidir. Tarifeler ve fiyatlar sık değişir, bugünkü teklifleri operatörün sitesinden bakın. Bu yüzden burada fiyat yazmıyoruz."},{"kind":"PRACTICAL","heading":"Evde internet","body":"Şehirlerdeki çoğu eve fiber internet bağlanabilir ve operatörler bunu çoğu zaman TV ile birlikte satar. Birçok kiralık dairede internet zaten vardır, ev sahibine sözleşmenin kimin adına olduğunu ve kiraya dahil olup olmadığını sorun. Yeni sözleşme için pasaportunuzu ve adresi getirin."},{"kind":"NOTES","heading":"eSIM almadan önce","body":"Telefonunuzun eSIM desteklediğini ve kendi ülkenizdeki bir operatöre kilitli olmadığını kontrol edin. Magti''de eSIM, MyMagti uygulamasından etkinleştirilebilir."}]},"ar":{"title":"رقم هاتف وإنترنت في البيت","summary":"الحصول على رقم جورجي سريع. خذ جوازك إلى متجر إحدى الشركات وستخرج وهاتفك يعمل. وإنترنت البيت غالبًا ألياف ضوئية وتركيبه سهل.","sections":[{"kind":"SHORT_ANSWER","heading":"باختصار","body":"هناك ثلاث شركات اتصالات: Magti وSilknet وCellfie. اذهب إلى متجر أي منها ومعك جوازك، لأن الرقم يُسجَّل باسمك. وإذا كان هاتفك يدعم eSIM فالشركات توفرها أيضًا، ويمكنك ترتيبها عبر الإنترنت قبل أن تصل."},{"kind":"WHERE","heading":"من أين تشتري","body":"من متاجر الشركات في كل المدن، ومن مطارات تبليسي وكوتايسي وباتومي. متجر المطار مريح في اليوم الأول، وMagti تبيع في المطارات شرائح خاصة بالسياح."},{"kind":"PRACTICAL","heading":"أي شركة تختار","body":"الثلاث تعمل جيدًا في المدن. أما في الجبال فتغطية Magti هي الأفضل عادة، وهذا مهم إذا كنت ستزور سفانيتي أو كازبيغي. الباقات والأسعار تتغير كثيرًا، فاطّلع على العروض الحالية في موقع الشركة نفسها، ولهذا لا نذكر أسعارًا هنا."},{"kind":"PRACTICAL","heading":"الإنترنت في البيت","body":"معظم البيوت في المدن يمكن توصيلها بإنترنت الألياف الضوئية، وكثيرًا ما تبيعه الشركات مع التلفزيون. وفي شقق إيجار كثيرة يكون الإنترنت موجودًا أصلًا، فاسأل المالك باسم من العقد وهل هو داخل في الإيجار. ولعقد جديد خذ جوازك واعرف العنوان."},{"kind":"NOTES","heading":"قبل أن تشتري eSIM","body":"تأكد أن هاتفك يدعم eSIM وأنه غير مقفل على شركة في بلدك. وفي Magti يمكنك تفعيل eSIM من تطبيق MyMagti."}]},"he":{"title":"מספר טלפון ואינטרנט בבית","summary":"להשיג מספר גאורגי זה מהיר. באים עם דרכון לחנות של מפעיל ויוצאים עם קליטה. אינטרנט ביתי הוא בדרך כלל סיבים, וקל לחבר אותו.","sections":[{"kind":"SHORT_ANSWER","heading":"בקצרה","body":"יש שלושה מפעילים סלולריים: Magti, Silknet ו־Cellfie. לכו לחנות של אחד מהם עם דרכון, כי המספר נרשם על שמכם. אם הטלפון תומך ב־eSIM, המפעילים מציעים גם את זה, ואפשר אפילו להסדיר אותו באינטרנט לפני שמגיעים."},{"kind":"WHERE","heading":"איפה קונים","body":"בחנויות של המפעילים בכל עיר ובשדות התעופה של טביליסי, קוטאיסי ובטומי. החנות בשדה נוחה ביום הראשון. Magti מוכרת בשדות התעופה סים לתיירים."},{"kind":"PRACTICAL","heading":"איזה מפעיל","body":"בערים שלושתם עובדים טוב. בהרים לרוב הכיסוי הכי טוב הוא של Magti, וזה חשוב אם אתם נוסעים למקומות כמו סוואנטי או קזבגי. החבילות והמחירים משתנים לעיתים קרובות, אז בדקו באתר של המפעיל מה מוצע היום. בגלל זה אנחנו לא כותבים כאן מחירים."},{"kind":"PRACTICAL","heading":"אינטרנט בבית","body":"ברוב הבתים בערים אפשר לחבר אינטרנט סיבים, והמפעילים מוכרים אותו הרבה פעמים יחד עם טלוויזיה. בהרבה דירות שכורות כבר יש אינטרנט, אז שאלו את בעל הדירה על שם מי החוזה והאם הוא כלול בשכירות. לחוזה חדש הביאו דרכון ואת הכתובת."},{"kind":"NOTES","heading":"לפני שקונים eSIM","body":"בדקו שהטלפון תומך ב־eSIM ושהוא לא נעול למפעיל בבית. ב־Magti אפשר להפעיל eSIM דרך האפליקציה MyMagti."}]}}'::jsonb,
        'PROCESS', 'PRACTICAL_CONTEXT', 60,
        true, false, null,
        now(), now() + interval '90 days')
