  fact_class = excluded.fact_class,
  register = excluded.register,
  sort_order = excluded.sort_order,
  published = excluded.published,
  needs_review = excluded.needs_review,
  review_reason = excluded.review_reason,
  last_verified_at = excluded.last_verified_at,
  review_due_at = excluded.review_due_at,
  updated_at = now();
insert into public.expat_topic_facts
  (topic_id, fact_key, fact_class, register, availability, statement, value,
   applies_to_nationalities, needs_review)
select id, 'sim-needs-passport', 'PROCESS', 'PRACTICAL_CONTEXT', 'ESTABLISHED',
       '{"en":"Georgia has three mobile operators, Magti, Silknet and Cellfie. You need your passport to buy a SIM card, and the operators also offer eSIMs.","ka":"საქართველოში სამი მობილური ოპერატორია: მაგთი, სილქნეტი და სელფი. სიმ ბარათის საყიდლად პასპორტი გჭირდებათ, ოპერატორები eSIM-საც გთავაზობენ.","ru":"В Грузии три мобильных оператора: Magti, Silknet и Cellfie. Чтобы купить SIM карту, нужен паспорт, операторы также предлагают eSIM.","tr":"Gürcistan''da üç mobil operatör var: Magti, Silknet ve Cellfie. SIM kart almak için pasaport gerekir, operatörler eSIM de sunar.","ar":"في جورجيا ثلاث شركات اتصالات: Magti وSilknet وCellfie. تحتاج إلى جوازك لشراء شريحة، والشركات توفر eSIM أيضًا.","he":"בגאורגיה יש שלושה מפעילים סלולריים: Magti, Silknet ו־Cellfie. כדי לקנות סים צריך דרכון, והמפעילים מציעים גם eSIM."}'::jsonb, '{"operators":["Magti","Silknet","Cellfie"]}'::jsonb, null,
       false
from public.expat_topics where slug = 'mobile-and-internet'
