insert into public.expat_fact_citations (fact_id, citation_id)
select f.id, c.id
from public.expat_topic_facts f
join public.expat_topics t on t.id = f.topic_id and t.slug = 'mobile-and-internet'
cross join lateral (
  select id from public.expat_citations
  where publisher = 'Madloba.info' and url is not distinct from 'https://madloba.info/en/faq/mobile-and-internet/buying-a-sim-card-in-georgia/'
  order by created_at limit 1) c
where f.fact_key = 'sim-needs-passport'
on conflict do nothing;
insert into public.expat_topic_facts
  (topic_id, fact_key, fact_class, register, availability, statement, value,
   applies_to_nationalities, needs_review)
select id, 'magti-esim-and-fibre', 'GENERAL', 'PRACTICAL_CONTEXT', 'ESTABLISHED',
       '{"en":"Magti offers eSIM, activated in the MyMagti app, sells tourist SIM cards at Georgian airports, and sells fibre optic home internet.","ka":"მაგთი გთავაზობთ eSIM-ს, რომელიც MyMagti აპლიკაციაში აქტიურდება, აეროპორტებში ტურისტულ სიმ ბარათებს ყიდის და ოპტიკურ სახლის ინტერნეტსაც გთავაზობთ.","ru":"Magti предлагает eSIM с активацией в приложении MyMagti, продаёт туристические SIM карты в аэропортах Грузии и подключает оптоволоконный домашний интернет.","tr":"Magti, MyMagti uygulamasından etkinleştirilen eSIM sunar, Gürcistan havalimanlarında turist SIM kartları satar ve fiber ev interneti sağlar.","ar":"تقدّم Magti شريحة eSIM تُفعَّل من تطبيق MyMagti، وتبيع شرائح للسياح في مطارات جورجيا، وتوفر إنترنت الألياف الضوئية للبيوت.","he":"Magti מציעה eSIM שמופעל באפליקציה MyMagti, מוכרת סים לתיירים בשדות התעופה בגאורגיה ומספקת אינטרנט סיבים לבית."}'::jsonb, null, null,
       false
